    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # Opposite-edge marker pairs define the full horizontal and vertical lines.
    horizontal = {
        r for r in range(h)
        if (r, 0) in markers and (r, w - 1) in markers
    }
    vertical = {
        c for c in range(w)
        if (0, c) in markers and (h - 1, c) in markers
    }

    out = [row[:] for row in grid]
    seen = set()

    # Recolor any 2-object touched by, or immediately bordering, a marker line.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            touches_line = False
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                if any(abs(y - rr) <= 1 for rr in horizontal) or \
                   any(abs(x - cc) <= 1 for cc in vertical):
                    touches_line = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if touches_line:
                for y, x in component:
                    out[y][x] = 1

    for rr in horizontal:
        for c in range(w):
            out[rr][c] = 1
    for cc in vertical:
        for r in range(h):
            out[r][cc] = 1
    return out
